# PROBE 4: Wilcoxon signed-rank + cluster bootstrap implementable with stdlib only?
import math, random, statistics
def wilcoxon(d):
    d=[x for x in d if x!=0]; n=len(d)
    order=sorted(range(n), key=lambda i: abs(d[i]))
    ranks=[0]*n; i=0
    while i<n:
        j=i
        while j+1<n and abs(d[order[j+1]])==abs(d[order[i]]): j+=1
        r=(i+j)/2+1.0
        for k in range(i,j+1): ranks[order[k]]=r
        i=j+1
    Wp=sum(r for x,r in zip(d,ranks) if x>0); Wm=sum(r for x,r in zip(d,ranks) if x<0)
    W=min(Wp,Wm); mu=n*(n+1)/4; sd=math.sqrt(n*(n+1)*(2*n+1)/24)
    z=(W-mu+0.5)/sd
    p=0.5*math.erfc(-z/math.sqrt(2))  # one-sided upper for increase
    return W, z, min(1.0,1-p)
random.seed(0)
d=[random.gauss(0.05,0.3) for _ in range(100)]
print("wilcoxon on synthetic shifted pairs:", tuple(round(v,4) for v in wilcoxon(d)))
d0=[random.gauss(0.0,0.3) for _ in range(100)]
print("wilcoxon on synthetic null pairs :", tuple(round(v,4) for v in wilcoxon(d0)))

def cluster_boot(d, B=20000, seed=1):
    r=random.Random(seed); n=len(d); est=[]
