da a,b:a+b, lambda a,b:a-b, lambda a,b:b-a, lambda a,b:a*b,\n     lambda a,b:a/b if b else None, lambda a,b:b/a if a else None]\ndef solvable(nums):\n    if len(nums)==1: return nums[0]==24\n    for a,b,i,j in [(nums[x],nums[y],x,y) for x in range(len(nums)) for y in range(len(nums)) if x!=y]:\n        rest=[nums[k] for k in range(len(nums)) if k not in (i,j)]\n        for f in ops:\n            v=f(a,b)\n            if v is not None and solvable(rest+[v]): return True\n    return False\nprint(\"Go24 verifier check: (2,2,3,9)->\", solvable([Fraction(2),Fraction(2),Fraction(3),Fraction(9)]),\n      \" (1,1,1,1)->\", solvable([Fraction(1)]*4))\nEOF", "exit_code": 0, "timed_out": false, "elapsed_seconds": 0.717, "output": "wilcoxon on synthetic shifted pairs: (2432.0, -0.318, 0.6248)\nwilcoxon on synthetic null pairs : (2516.0, -0.0292, 0.5117)\ncluster-bootstrap 95% CI on median log-ratio (synthetic): -0.0884 0.0741\nstdlib TOST feasible: True\nGo24 verifier check: (2,2,3,9)-> True  (1,1,1,1)-> False\n", "output_truncated": false}"}], "is_error": false, "kind": "BenchmarkObservation"}, "action_id": "fdd39765-8cec-43cc-8276-a08d96a53204", "extended_content": [], "kind": "ObservationEvent"}
